// Extract the markdown content from GitHub API response
const items = $input.all();
const item = items[0];

let content = '';
let sha = '';

if (item.json.content) {
  if (item.json.encoding === 'base64') {
    content = Buffer.from(item.json.content, 'base64').toString('utf-8');
  } else {
    content = item.json.content;
  }
  sha = item.json.sha || '';
} else if (typeof item.json === 'string') {
  content = item.json;
}

// Pre-number every line so the LLM can read line numbers instead of counting
const lines = content.split('\n');
const numbered = lines.map((line, i) => `[L${i + 1}] ${line}`).join('\n');

return [{
  json: {
    markdown_content: content,
    numbered_content: numbered,
    file_sha: sha,
    repo_owner: $('Set Input Variables').item.json.repo_owner,
    repo_name: $('Set Input Variables').item.json.repo_name,
    file_path: $('Set Input Variables').item.json.file_path,
    branch: $('Set Input Variables').item.json.branch
  }
}];

// ============================================
// PATCH ENGINE
// Applies line-level edits safely and predictably
// ============================================

const originalContent = $('Extract File Content').item.json.markdown_content;
const editsData = $input.item.json.output || $input.item.json;
const edits = editsData.edits || [];
const skippedByAgent = editsData.skipped_issues || [];

// Split into lines (1-indexed to match LLM output)
const lines = originalContent.split('\n');
const totalLines = lines.length;

// Track operations
const applied = [];
const skipped = [];
let aborted = false;

// Safety check: if >50% of lines would be modified, abort
const uniqueLinesAffected = new Set(edits.map(e => e.line_number)).size;
if (uniqueLinesAffected > totalLines * 0.5) {
  aborted = true;
  return [{
    json: {
      patched_content: originalContent,
      operations_log: {
        applied: [],
        skipped: [],
        skipped_by_agent: skippedByAgent,
        aborted: true,
        abort_reason: `${uniqueLinesAffected} of ${totalLines} lines would be modified (>${Math.round(totalLines * 0.5)}). Article likely needs a full rewrite, not patching.`
      }
    }
  }];
}

// Helper: find the actual line index for an edit using original_text as fallback
function findLineIndex(edit) {
  const lineIndex = edit.line_number - 1; // Convert to 0-indexed

  // First: try the specified line number
  if (lineIndex >= 0 && lineIndex < lines.length && edit.original_text) {
    const actualLine = lines[lineIndex].trim();
    const expectedText = edit.original_text.trim();
    // Guard: skip empty-string matches (empty lines match everything)
    if (actualLine.length > 0 && expectedText.length > 0) {
      if (actualLine === expectedText || actualLine.includes(expectedText) || expectedText.includes(actualLine)) {
        return lineIndex;
      }
    }
  }

  // Fallback: search all lines for original_text match
  if (edit.original_text) {
    const expectedText = edit.original_text.trim();
    if (expectedText.length > 0) {
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i].trim();
        // Guard: skip empty lines in fallback search too
        if (line.length > 0 && (line === expectedText || line.includes(expectedText) || expectedText.includes(line))) {
          return i;
        }
      }
    }
  }

  // No match found anywhere
  return -1;
}

// Sort edits in REVERSE line order (highest first)
// This prevents line-number drift when inserting or deleting
const sortedEdits = [...edits].sort((a, b) => b.line_number - a.line_number);

for (const edit of sortedEdits) {
  // Find the correct line using line number + original_text fallback
  const resolvedIndex = findLineIndex(edit);

  if (resolvedIndex === -1) {
    skipped.push({
      ...edit,
      skip_reason: edit.original_text 
        ? `Could not find matching text: "${edit.original_text.substring(0, 60)}..." anywhere in the file`
        : `Line number ${edit.line_number} is out of range and no original_text provided for fallback`
    });
    continue;
  }

  // Apply the operation
  switch (edit.operation) {
    case 'replace':
      const actualLine = lines[resolvedIndex];
      const trimmedActual = actualLine.trim();
      const trimmedOriginal = (edit.original_text || '').trim();

      if (trimmedActual === trimmedOriginal || trimmedOriginal.includes(trimmedActual)) {
        // Full line match (or original_text contains the line) — replace the whole line
        lines[resolvedIndex] = edit.new_text;
        applied.push({ 
          ...edit, 
          status: 'applied',
          resolved_line: resolvedIndex + 1,
          matched_by: resolvedIndex === (edit.line_number - 1) ? 'line_number' : 'original_text_search',
          replace_mode: 'full_line'
        });
      } else if (trimmedActual.includes(trimmedOriginal) && trimmedOriginal.length > 0) {
        // Partial match — original_text is a SUBSTRING of the line
        // Do a targeted substring replacement to avoid content loss
        lines[resolvedIndex] = actualLine.replace(trimmedOriginal, (edit.new_text || '').trim());
        applied.push({ 
          ...edit, 
          status: 'applied',
          resolved_line: resolvedIndex + 1,
          matched_by: resolvedIndex === (edit.line_number - 1) ? 'line_number' : 'original_text_search',
          replace_mode: 'substring'
        });
      } else {
        // Shouldn't happen if findLineIndex worked, but just in case
        lines[resolvedIndex] = edit.new_text;
        applied.push({ 
          ...edit, 
          status: 'applied',
          resolved_line: resolvedIndex + 1,
          matched_by: 'fallback',
          replace_mode: 'full_line'
        });
      }
      break;

    case 'insert_after':
      lines.splice(resolvedIndex + 1, 0, edit.new_text);
      applied.push({ 
        ...edit, 
        status: 'applied',
        resolved_line: resolvedIndex + 1,
        matched_by: resolvedIndex === (edit.line_number - 1) ? 'line_number' : 'original_text_search'
      });
      break;

    case 'delete':
      lines.splice(resolvedIndex, 1);
      applied.push({ 
        ...edit, 
        status: 'applied',
        resolved_line: resolvedIndex + 1,
        matched_by: resolvedIndex === (edit.line_number - 1) ? 'line_number' : 'original_text_search'
      });
      break;

    default:
      skipped.push({
        ...edit,
        skip_reason: `Unknown operation: ${edit.operation}`
      });
  }
}

return [{
  json: {
    patched_content: lines.join('\n'),
    operations_log: {
      applied,
      skipped,
      skipped_by_agent: skippedByAgent,
      aborted: false,
      total_edits_requested: edits.length,
      total_applied: applied.length,
      total_skipped: skipped.length
    }
  }
}];

// ============================================
// GENERATE QA REPORT
// Creates a Markdown report of the QA findings
// ============================================

const qaOutput = $('Run QA Analysis').item.json.output || $('Run QA Analysis').item.json;
const patchLog = $input.item.json.operations_log;
const patchedContent = $input.item.json.patched_content;
const filePath = $('Set Input Variables').item.json.file_path;

// --- Score calculation with rubric support ---
const breakdown = qaOutput.score_breakdown || null;
const weights = {
  grammar_mechanics: 0.25,
  brand_voice: 0.25,
  clarity_readability: 0.20,
  structure_flow: 0.15,
  completeness_depth: 0.15
};

let score;
if (breakdown && breakdown.grammar_mechanics && breakdown.brand_voice && breakdown.clarity_readability && breakdown.structure_flow && breakdown.completeness_depth) {
  // Recalculate from dimension scores (don't trust LLM arithmetic)
  score = Math.round(
    (breakdown.grammar_mechanics.score || 0) * weights.grammar_mechanics +
    (breakdown.brand_voice.score || 0) * weights.brand_voice +
    (breakdown.clarity_readability.score || 0) * weights.clarity_readability +
    (breakdown.structure_flow.score || 0) * weights.structure_flow +
    (breakdown.completeness_depth.score || 0) * weights.completeness_depth
  );
} else {
  // Fallback: use raw quality_score with 0-10 normalization
  score = (qaOutput.quality_score != null && qaOutput.quality_score <= 10)
    ? qaOutput.quality_score * 10
    : (qaOutput.quality_score || 0);
}

const now = new Date();
const dateStr = now.toISOString().split('T')[0];
const timestamp = now.toISOString();

let report = `# QA Report: ${filePath}\n\n`;
report += `**Generated:** ${timestamp}\n`;
report += `**Quality Score:** ${score}/100\n\n`;
report += `## Summary\n\n${qaOutput.summary || 'No summary available.'}\n\n`;

// Score breakdown table
if (breakdown && breakdown.grammar_mechanics) {
  report += `## Score Breakdown\n\n`;
  report += `| Dimension | Weight | Score | Rationale |\n`;
  report += `|-----------|--------|-------|-----------|\n`;
  const dims = [
    { key: 'grammar_mechanics', label: 'Grammar & Mechanics', weight: '25%' },
    { key: 'brand_voice', label: 'Brand Voice', weight: '25%' },
    { key: 'clarity_readability', label: 'Clarity & Readability', weight: '20%' },
    { key: 'structure_flow', label: 'Structure & Flow', weight: '15%' },
    { key: 'completeness_depth', label: 'Completeness & Depth', weight: '15%' }
  ];
  for (const dim of dims) {
    const d = breakdown[dim.key] || {};
    const dimScore = d.score != null ? d.score : 'N/A';
    const rationale = (d.rationale || 'No rationale provided').replace(/\|/g, '/');
    report += `| ${dim.label} | ${dim.weight} | ${dimScore} | ${rationale} |\n`;
  }
  report += `\n`;
}

report += `## Issues Found (${(qaOutput.issues || []).length})\n\n`;
if (qaOutput.issues && qaOutput.issues.length > 0) {
  report += `| Line | Type | Severity | Description |\n`;
  report += `|------|------|----------|-------------|\n`;
  for (const issue of qaOutput.issues) {
    report += `| ${issue.line_number} | ${issue.issue_type} | ${issue.severity} | ${issue.description} |\n`;
  }
}

report += `\n## Edits Applied (${patchLog.total_applied || 0})\n\n`;
if (patchLog.applied && patchLog.applied.length > 0) {
  report += `| Line | Operation | Description |\n`;
  report += `|------|-----------|-------------|\n`;
  for (const edit of patchLog.applied) {
    const desc = edit.operation === 'delete' ? 'Line removed' : (edit.new_text || '').substring(0, 80);
    report += `| ${edit.line_number} | ${edit.operation} | ${desc} |\n`;
  }
}

if ((patchLog.skipped && patchLog.skipped.length > 0) || (patchLog.skipped_by_agent && patchLog.skipped_by_agent.length > 0)) {
  const totalSkipped = (patchLog.skipped || []).length + (patchLog.skipped_by_agent || []).length;
  report += `\n## Edits Skipped (${totalSkipped})\n\n`;
  if (patchLog.skipped && patchLog.skipped.length > 0) {
    for (const s of patchLog.skipped) {
      report += `- **Line ${s.line_number}:** ${s.skip_reason}\n`;
    }
  }
  if (patchLog.skipped_by_agent && patchLog.skipped_by_agent.length > 0) {
    for (const s of patchLog.skipped_by_agent) {
      report += `- **Line ${s.line_number}:** ${s.reason}\n`;
    }
  }
}

if (patchLog.aborted) {
  report += `\n## \u26a0\ufe0f Patching Aborted\n\n${patchLog.abort_reason}\n`;
}

report += `\n---\n*Generated by the Blog QA Pipeline*\n`;

const fileName = filePath.split('/').pop().replace('.md', '');
const fileDir = filePath.substring(0, filePath.lastIndexOf('/'));
const branchName = `ai-qa/${fileName}-${dateStr}`;
const reportPath = fileDir ? `${fileDir}/qa-report-${dateStr}.md` : `qa-report-${dateStr}.md`;

// Pre-encode content as base64 for GitHub API (Buffer not available in n8n expressions)
const patchedContentBase64 = Buffer.from(patchedContent).toString('base64');
const qaReportBase64 = Buffer.from(report).toString('base64');

return [{
  json: {
    patched_content: patchedContent,
    patched_content_base64: patchedContentBase64,
    qa_report: report,
    qa_report_base64: qaReportBase64,
    branch_name: branchName,
    report_path: reportPath,
    file_path: filePath,
    quality_score: score,
    score_breakdown: breakdown,
    issues_found: (qaOutput.issues || []).length,
    edits_applied: patchLog.total_applied || 0,
    edits_skipped: patchLog.total_skipped || 0,
    summary: qaOutput.summary || '',
    operations_log: patchLog
  }
}];

